163      private static ArrayList<FType> instanceOf(List<StaticParam> tparams,
164                                                 LatticeIntervalMap<String, FType, TypeLatticeOps> abm,
165                                                 Set<String> fixable, Set<String> aboveOnly,
166                                                 Collection<StaticParam> rechecks,
167                                                 boolean bounded, GenericFunctionOrMethod appliedThing,
168                                                 List<FValue> args) {
169          ArrayList<FType> tl = new ArrayList<FType>(tparams.size());
170          boolean bounds = bounded && !bigOperator(appliedThing);
171          Set<String> fixed = bounds ? fixedThroughBounds(tparams, fixable) : fixable;
172          for (StaticParam tp : tparams) {
173              String n = NodeUtil.getName(tp);
174              FType t = abm.get(n);
175              boolean unfixed = !fixed.contains(n);
176              if (bounds && NodeUtil.isTypeParam(tp) && (unfixed || aboveOnly.contains(n)) &&
177                  (rechecks == null || !rechecks.contains(tp)) && (t == null || t instanceof BottomType)) {
178                  t = boundOf(abm, n);
179                  traceInstance(unfixed ? "unfixed" : "above", appliedThing, n, BottomType.ONLY, t, typesOf(args));
180              }
181              if (t == null) t = BottomType.ONLY;
182              tl.add(t);
183          }
184          if (bounded && rechecks != null) {
185              Set<String> fixedAll = fixedThroughBounds(tparams, fixable);
186              for (int i = 0; i < tparams.size(); i++) {
187                  StaticParam tp = tparams.get(i);
188                  String n = NodeUtil.getName(tp);
189                  if (!NodeUtil.isTypeParam(tp) || fixedAll.contains(n) || !rechecks.contains(tp) ||
190                      !(tl.get(i) instanceof BottomType) || !mentionsItself(tp)) continue;
191                  traceInstance("open", appliedThing, n, BottomType.ONLY, BottomType.OPEN, typesOf(args));
192                  tl.set(i, BottomType.OPEN);
193              }
194          }
195          if (!bounds || rechecks == null) return tl;
196          for (int i = 0; i < tparams.size(); i++) {
197              StaticParam tp = tparams.get(i);
198              String n = NodeUtil.getName(tp);
199              if (!NodeUtil.isTypeParam(tp) || fixed.contains(n) || !rechecks.contains(tp) ||
200                  !(tl.get(i) instanceof BottomType)) continue;
201              FType b = boundAtInstances(tp, tparams, tl, appliedThing);
202              if (b != null) {
203                  traceInstance("unfixed", appliedThing, n, BottomType.ONLY, b, typesOf(args));
204                  tl.set(i, b);
205              }
206          }
207          return tl;
208      }

